function solve(haystack, needle) {
  const n = haystack.length;
  const m = needle.length;
  for (let start = 0; start + m <= n; start++) {
    let matched = 0;
    while (matched < m && haystack[start + matched] === needle[matched]) {
      matched++;
    }
    if (matched === m) return start;
  }
  return -1;
}

function solve(haystack, needle) {
  const n = haystack.length;
  const m = needle.length;
  if (m === 0) return 0;
  const fail = new Array(m).fill(0);
  for (let i = 1; i < m; i++) {
    let j = fail[i - 1];
    while (j > 0 && needle[i] !== needle[j]) j = fail[j - 1];
    if (needle[i] === needle[j]) j++;
    fail[i] = j;
  }
  let j = 0;
  for (let i = 0; i < n; i++) {
    while (j > 0 && haystack[i] !== needle[j]) j = fail[j - 1];
    if (haystack[i] === needle[j]) j++;
    if (j === m) return i - m + 1;
  }
  return -1;
}
